const fmt = n => (Number(n) || 0).toLocaleString();
const todayISO = () => new Date().toISOString().split('T')[0];
const tsFromDate = d => { if (d === todayISO()) return Date.now(); const dt = new Date(d); dt.setHours(12,0,0,0); return isNaN(dt.getTime()) ? Date.now() : dt.getTime(); };
const toDateStr = ts => { const d = new Date(ts); return d.toLocaleDateString('en-GB') + ', ' + d.toLocaleTimeString('en-GB'); };
const simpleHash = s => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return 'h_' + h.toString(16).padStart(8, '0'); };
const parseCSVLine = (t) => { let r = [], q = false, v = ''; for (let i = 0; i < t.length; i++) { let c = t[i]; if (c === '"') { if (q && t[i+1] === '"') { v += '"'; i++; } else q = !q; } else if (c === ',' && !q) { r.push(v.trim()); v = ''; } else v += c; } r.push(v.trim()); return r.map(x => x.replace(/^"|"$/g, '')); };
const downloadFile = (fn, ct) => { const b = new Blob(['\uFEFF' + ct], { type: 'text/csv' }); const a = document.createElement('a'); a.href = URL.createObjectURL(b); a.download = fn; a.click(); };
